INSERT INTO practice_exercises(number,collection,source_number,title,source_url,source_page,definition) VALUES(11001,'scales',11001,'1. C major · Five-finger preparation','',0,'{"number":11001,"title":"1. C major · Five-finger preparation","collection":"scales","composer":"PianoPath scale studies","arrangement":"Standard scale fingerings with original preparatory patterns.","difficulty":"Beginner · C major","description":"C major uses only white keys. Practise right hand, then left hand, then both hands when comfortable. MIDI checks correct notes at your own pace.","learningFocus":"Find C–G and play connected steps without moving position.","practiceTip":"Start with RH thumb on middle C (C4), LH little finger on C3. Keep the hand relaxed. This five-finger drill uses a different F fingering from the full scale.","beatsPerMeasure":4,"measuresPerSystem":4,"tempoBpm":60,"right":[[{"pitch":60,"beats":1,"tie":false,"finger":1},{"pitch":62,"beats":1,"tie":false,"finger":2},{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":65,"beats":1,"tie":false,"finger":4}],[{"pitch":67,"beats":1,"tie":false,"finger":5},{"pitch":65,"beats":1,"tie":false,"finger":4},{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":62,"beats":1,"tie":false,"finger":2}],[{"pitch":60,"beats":1,"tie":false,"finger":1},{"pitch":62,"beats":1,"tie":false,"finger":2},{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":65,"beats":1,"tie":false,"finger":4}],[{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":62,"beats":1,"tie":false,"finger":2},{"pitch":60,"beats":2,"tie":false,"finger":1}]],"left":[[{"pitch":48,"beats":1,"tie":false,"finger":5},{"pitch":50,"beats":1,"tie":false,"finger":4},{"pitch":52,"beats":1,"tie":false,"finger":3},{"pitch":53,"beats":1,"tie":false,"finger":2}],[{"pitch":55,"beats":1,"tie":false,"finger":1},{"pitch":53,"beats":1,"tie":false,"finger":2},{"pitch":52,"beats":1,"tie":false,"finger":3},{"pitch":50,"beats":1,"tie":false,"finger":4}],[{"pitch":48,"beats":1,"tie":false,"finger":5},{"pitch":50,"beats":1,"tie":false,"finger":4},{"pitch":52,"beats":1,"tie":false,"finger":3},{"pitch":53,"beats":1,"tie":false,"finger":2}],[{"pitch":52,"beats":1,"tie":false,"finger":3},{"pitch":50,"beats":1,"tie":false,"finger":4},{"pitch":48,"beats":2,"tie":false,"finger":5}]]}') ON CONFLICT(number) DO NOTHING;
INSERT INTO practice_exercises(number,collection,source_number,title,source_url,source_page,definition) VALUES(11002,'scales',11002,'2. C major · Right-hand thumb passage','',0,'{"number":11002,"title":"2. C major · Right-hand thumb passage","collection":"scales","composer":"PianoPath scale studies","arrangement":"Standard scale fingerings with original preparatory patterns.","difficulty":"Beginner · C major","description":"C major uses only white keys. Practise right hand, then left hand, then both hands when comfortable. MIDI checks correct notes at your own pace.","learningFocus":"RH: move from finger 3 on E to thumb on F, then return.","practiceTip":"Select Right hand first. Move the hand sideways as the thumb passes under; coming down, finger 3 crosses over from F to E. Add the simple left-hand line later.","beatsPerMeasure":4,"measuresPerSystem":4,"tempoBpm":60,"right":[[{"pitch":60,"beats":1,"tie":false,"finger":1},{"pitch":62,"beats":1,"tie":false,"finger":2},{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":65,"beats":1,"tie":false,"finger":1}],[{"pitch":67,"beats":1,"tie":false,"finger":2},{"pitch":65,"beats":1,"tie":false,"finger":1},{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":62,"beats":1,"tie":false,"finger":2}],[{"pitch":60,"beats":1,"tie":false,"finger":1},{"pitch":62,"beats":1,"tie":false,"finger":2},{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":65,"beats":1,"tie":false,"finger":1}],[{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":62,"beats":1,"tie":false,"finger":2},{"pitch":60,"beats":2,"tie":false,"finger":1}]],"left":[[{"pitch":48,"beats":1,"tie":false,"finger":5},{"pitch":50,"beats":1,"tie":false,"finger":4},{"pitch":52,"beats":1,"tie":false,"finger":3},{"pitch":53,"beats":1,"tie":false,"finger":2}],[{"pitch":55,"beats":1,"tie":false,"finger":1},{"pitch":53,"beats":1,"tie":false,"finger":2},{"pitch":52,"beats":1,"tie":false,"finger":3},{"pitch":50,"beats":1,"tie":false,"finger":4}],[{"pitch":48,"beats":1,"tie":false,"finger":5},{"pitch":50,"beats":1,"tie":false,"finger":4},{"pitch":52,"beats":1,"tie":false,"finger":3},{"pitch":53,"beats":1,"tie":false,"finger":2}],[{"pitch":52,"beats":1,"tie":false,"finger":3},{"pitch":50,"beats":1,"tie":false,"finger":4},{"pitch":48,"beats":2,"tie":false,"finger":5}]]}') ON CONFLICT(number) DO NOTHING;
INSERT INTO practice_exercises(number,collection,source_number,title,source_url,source_page,definition) VALUES(11003,'scales',11003,'3. C major · Left-hand finger crossing','',0,'{"number":11003,"title":"3. C major · Left-hand finger crossing","collection":"scales","composer":"PianoPath scale studies","arrangement":"Standard scale fingerings with original preparatory patterns.","difficulty":"Beginner · C major","description":"C major uses only white keys. Practise right hand, then left hand, then both hands when comfortable. MIDI checks correct notes at your own pace.","learningFocus":"LH: finger 3 crosses over the thumb from G to A.","practiceTip":"Select Left hand first. Start LH thumb on G3. Return from A to G with the thumb passing under. RH starts finger 2 on G4.","beatsPerMeasure":4,"measuresPerSystem":4,"tempoBpm":60,"right":[[{"pitch":67,"beats":1,"tie":false,"finger":2},{"pitch":69,"beats":1,"tie":false,"finger":3},{"pitch":71,"beats":1,"tie":false,"finger":4},{"pitch":72,"beats":1,"tie":false,"finger":5}],[{"pitch":71,"beats":1,"tie":false,"finger":4},{"pitch":69,"beats":1,"tie":false,"finger":3},{"pitch":67,"beats":1,"tie":false,"finger":2},{"pitch":65,"beats":1,"tie":false,"finger":1}],[{"pitch":67,"beats":1,"tie":false,"finger":2},{"pitch":69,"beats":1,"tie":false,"finger":3},{"pitch":71,"beats":1,"tie":false,"finger":4},{"pitch":72,"beats":1,"tie":false,"finger":5}],[{"pitch":71,"beats":1,"tie":false,"finger":4},{"pitch":69,"beats":1,"tie":false,"finger":3},{"pitch":67,"beats":2,"tie":false,"finger":2}]],"left":[[{"pitch":55,"beats":1,"tie":false,"finger":1},{"pitch":57,"beats":1,"tie":false,"finger":3},{"pitch":59,"beats":1,"tie":false,"finger":2},{"pitch":60,"beats":1,"tie":false,"finger":1}],[{"pitch":59,"beats":1,"tie":false,"finger":2},{"pitch":57,"beats":1,"tie":false,"finger":3},{"pitch":55,"beats":1,"tie":false,"finger":1},{"pitch":53,"beats":1,"tie":false,"finger":2}],[{"pitch":55,"beats":1,"tie":false,"finger":1},{"pitch":57,"beats":1,"tie":false,"finger":3},{"pitch":59,"beats":1,"tie":false,"finger":2},{"pitch":60,"beats":1,"tie":false,"finger":1}],[{"pitch":59,"beats":1,"tie":false,"finger":2},{"pitch":57,"beats":1,"tie":false,"finger":3},{"pitch":55,"beats":2,"tie":false,"finger":1}]]}') ON CONFLICT(number) DO NOTHING;
INSERT INTO practice_exercises(number,collection,source_number,title,source_url,source_page,definition) VALUES(11004,'scales',11004,'4. C major · One octave ascending','',0,'{"number":11004,"title":"4. C major · One octave ascending","collection":"scales","composer":"PianoPath scale studies","arrangement":"Standard scale fingerings with original preparatory patterns.","difficulty":"Beginner · C major","description":"C major uses only white keys. Practise right hand, then left hand, then both hands when comfortable. MIDI checks correct notes at your own pace.","learningFocus":"Connect C to the next C using each hand’s own crossing.","practiceTip":"RH: 1-2-3, 1-2-3-4-5. LH: 5-4-3-2-1, 3-2-1. The hands cross at different places; learn each alone first.","beatsPerMeasure":4,"measuresPerSystem":4,"tempoBpm":60,"right":[[{"pitch":60,"beats":1,"tie":false,"finger":1},{"pitch":62,"beats":1,"tie":false,"finger":2},{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":65,"beats":1,"tie":false,"finger":1}],[{"pitch":67,"beats":1,"tie":false,"finger":2},{"pitch":69,"beats":1,"tie":false,"finger":3},{"pitch":71,"beats":1,"tie":false,"finger":4},{"pitch":72,"beats":1,"tie":false,"finger":5}]],"left":[[{"pitch":48,"beats":1,"tie":false,"finger":5},{"pitch":50,"beats":1,"tie":false,"finger":4},{"pitch":52,"beats":1,"tie":false,"finger":3},{"pitch":53,"beats":1,"tie":false,"finger":2}],[{"pitch":55,"beats":1,"tie":false,"finger":1},{"pitch":57,"beats":1,"tie":false,"finger":3},{"pitch":59,"beats":1,"tie":false,"finger":2},{"pitch":60,"beats":1,"tie":false,"finger":1}]]}') ON CONFLICT(number) DO NOTHING;
INSERT INTO practice_exercises(number,collection,source_number,title,source_url,source_page,definition) VALUES(11005,'scales',11005,'5. C major · One octave descending','',0,'{"number":11005,"title":"5. C major · One octave descending","collection":"scales","composer":"PianoPath scale studies","arrangement":"Standard scale fingerings with original preparatory patterns.","difficulty":"Beginner · C major","description":"C major uses only white keys. Practise right hand, then left hand, then both hands when comfortable. MIDI checks correct notes at your own pace.","learningFocus":"Reverse the scale smoothly from upper C to lower C.","practiceTip":"RH starts finger 5 on C5; LH starts thumb on C4. RH finger 3 crosses at F–E; LH thumb passes under at A–G.","beatsPerMeasure":4,"measuresPerSystem":4,"tempoBpm":60,"right":[[{"pitch":72,"beats":1,"tie":false,"finger":5},{"pitch":71,"beats":1,"tie":false,"finger":4},{"pitch":69,"beats":1,"tie":false,"finger":3},{"pitch":67,"beats":1,"tie":false,"finger":2}],[{"pitch":65,"beats":1,"tie":false,"finger":1},{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":62,"beats":1,"tie":false,"finger":2},{"pitch":60,"beats":1,"tie":false,"finger":1}]],"left":[[{"pitch":60,"beats":1,"tie":false,"finger":1},{"pitch":59,"beats":1,"tie":false,"finger":2},{"pitch":57,"beats":1,"tie":false,"finger":3},{"pitch":55,"beats":1,"tie":false,"finger":1}],[{"pitch":53,"beats":1,"tie":false,"finger":2},{"pitch":52,"beats":1,"tie":false,"finger":3},{"pitch":50,"beats":1,"tie":false,"finger":4},{"pitch":48,"beats":1,"tie":false,"finger":5}]]}') ON CONFLICT(number) DO NOTHING;
INSERT INTO practice_exercises(number,collection,source_number,title,source_url,source_page,definition) VALUES(11006,'scales',11006,'6. C major · One octave up and down','',0,'{"number":11006,"title":"6. C major · One octave up and down","collection":"scales","composer":"PianoPath scale studies","arrangement":"Standard scale fingerings with original preparatory patterns.","difficulty":"Beginner · C major","description":"C major uses only white keys. Practise right hand, then left hand, then both hands when comfortable. MIDI checks correct notes at your own pace.","learningFocus":"Join ascending and descending motion without repeating the top C.","practiceTip":"Play the upper C once, then change direction. Aim for comfortable, even movement before trying to go faster.","beatsPerMeasure":4,"measuresPerSystem":4,"tempoBpm":60,"right":[[{"pitch":60,"beats":1,"tie":false,"finger":1},{"pitch":62,"beats":1,"tie":false,"finger":2},{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":65,"beats":1,"tie":false,"finger":1}],[{"pitch":67,"beats":1,"tie":false,"finger":2},{"pitch":69,"beats":1,"tie":false,"finger":3},{"pitch":71,"beats":1,"tie":false,"finger":4},{"pitch":72,"beats":1,"tie":false,"finger":5}],[{"pitch":71,"beats":1,"tie":false,"finger":4},{"pitch":69,"beats":1,"tie":false,"finger":3},{"pitch":67,"beats":1,"tie":false,"finger":2},{"pitch":65,"beats":1,"tie":false,"finger":1}],[{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":62,"beats":1,"tie":false,"finger":2},{"pitch":60,"beats":2,"tie":false,"finger":1}]],"left":[[{"pitch":48,"beats":1,"tie":false,"finger":5},{"pitch":50,"beats":1,"tie":false,"finger":4},{"pitch":52,"beats":1,"tie":false,"finger":3},{"pitch":53,"beats":1,"tie":false,"finger":2}],[{"pitch":55,"beats":1,"tie":false,"finger":1},{"pitch":57,"beats":1,"tie":false,"finger":3},{"pitch":59,"beats":1,"tie":false,"finger":2},{"pitch":60,"beats":1,"tie":false,"finger":1}],[{"pitch":59,"beats":1,"tie":false,"finger":2},{"pitch":57,"beats":1,"tie":fa