INSERT INTO practice_exercises(number,collection,source_number,title,source_url,source_page,definition) VALUES(11007,'scales',11007,'7. C major · Contrary motion','',0,'{"number":11007,"title":"7. C major · Contrary motion","collection":"scales","composer":"PianoPath scale studies","arrangement":"Standard scale fingerings with original preparatory patterns.","difficulty":"Beginner · C major","description":"C major uses only white keys. Practise right hand, then left hand, then both hands when comfortable. MIDI checks correct notes at your own pace.","learningFocus":"Move the hands apart and back together with matching finger numbers.","practiceTip":"Begin RH thumb on C4 and LH thumb on C3. RH rises to C5 while LH descends to C2, then both return. Practise each hand separately before combining.","beatsPerMeasure":4,"measuresPerSystem":4,"tempoBpm":60,"right":[[{"pitch":60,"beats":1,"tie":false,"finger":1},{"pitch":62,"beats":1,"tie":false,"finger":2},{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":65,"beats":1,"tie":false,"finger":1}],[{"pitch":67,"beats":1,"tie":false,"finger":2},{"pitch":69,"beats":1,"tie":false,"finger":3},{"pitch":71,"beats":1,"tie":false,"finger":4},{"pitch":72,"beats":1,"tie":false,"finger":5}],[{"pitch":71,"beats":1,"tie":false,"finger":4},{"pitch":69,"beats":1,"tie":false,"finger":3},{"pitch":67,"beats":1,"tie":false,"finger":2},{"pitch":65,"beats":1,"tie":false,"finger":1}],[{"pitch":64,"beats":1,"tie":false,"finger":3},{"pitch":62,"beats":1,"tie":false,"finger":2},{"pitch":60,"beats":2,"tie":false,"finger":1}]],"left":[[{"pitch":48,"beats":1,"tie":false,"finger":1},{"pitch":47,"beats":1,"tie":false,"finger":2},{"pitch":45,"beats":1,"tie":false,"finger":3},{"pitch":43,"beats":1,"tie":false,"finger":1}],[{"pitch":41,"beats":1,"tie":false,"finger":2},{"pitch":40,"beats":1,"tie":false,"finger":3},{"pitch":38,"beats":1,"tie":false,"finger":4},{"pitch":36,"beats":1,"tie":false,"finger":5}],[{"pitch":38,"beats":1,"tie":false,"finger":4},{"p